import{_ as p,a0 as d,w as o,s as r,ao as l,I as i,x as s,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"在 Linux 上安装 NetData 性能监控工具 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安装 NetData 性能监控工具 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安装 NetData 性能监控工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安装 NetData 性能监控工具 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190706 Install NetData Performance Monitoring Tool On Linux","title":"在 Linux 上安装 NetData 性能监控工具","tag":"201908","desc":""},"relativePath":"201908/20190706 Install NetData Performance Monitoring Tool On Linux.md","filePath":"[post].md"}'),h={name:"201908/20190706 Install NetData Performance Monitoring Tool On Linux.md"};function c(u,a,g,b,k,f){const n=d("Link");return o(),r("div",null,[a[23]||(a[23]=l('<h1 id="在-linux-上安装-netdata-性能监控工具" tabindex="-1">在 Linux 上安装 NetData 性能监控工具 <a class="header-anchor" href="#在-linux-上安装-netdata-性能监控工具" aria-label="Permalink to “在 Linux 上安装 NetData 性能监控工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Install-netdata-720x340.png" alt=""></p><p><strong>NetData</strong> 是一个用于系统和应用的分布式实时性能和健康监控工具。它提供了对系统中实时发生的所有事情的全面检测。你可以在高度互动的 Web 仪表板中查看结果。使用 Netdata，你可以清楚地了解现在发生的事情，以及之前系统和应用中发生的事情。你无需成为专家即可在 Linux 系统中部署此工具。NetData 开箱即用，零配置、零依赖。只需安装它然后坐等，之后 NetData 将负责其余部分。</p><p>它有自己的内置 Web 服务器，以图形形式显示结果。NetData 非常快速高效，安装后可立即开始分析系统性能。它是用 C 编程语言编写的，所以它非常轻量。它占用的单核 CPU 使用率不到 3％，内存占用 10-15MB。我们可以轻松地在任何现有网页上嵌入图表，并且它还有一个插件 API，以便你可以监控任何应用。</p><p>以下是 Linux 系统中 NetData 的监控列表。</p><ul><li>CPU 使用率</li><li>RAM 使用率</li><li>交换内存使用率</li><li>内核内存使用率</li><li>硬盘及其使用率</li><li>网络接口</li><li>IPtables</li><li>Netfilter</li><li>DDoS 保护</li><li>进程</li><li>应用</li><li>NFS 服务器</li><li>Web 服务器 （Apache 和 Nginx）</li><li>数据库服务器 （MySQL），</li><li>DHCP 服务器</li><li>DNS 服务器</li><li>电子邮件服务</li><li>代理服务器</li><li>Tomcat</li><li>PHP</li><li>SNP 设备</li><li>等等</li></ul><p>NetData 是自由开源工具，它支持 Linux、FreeBSD 和 Mac OS。</p><h3 id="在-linux-上安装-netdata" tabindex="-1">在 Linux 上安装 NetData <a class="header-anchor" href="#在-linux-上安装-netdata" aria-label="Permalink to “在 Linux 上安装 NetData”">​</a></h3><p>Netdata 可以安装在任何安装了 Bash 的 Linux 发行版上。</p><p>最简单的安装 Netdata 的方法是从终端运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ bash &lt;(curl -Ss https://my-netdata.io/kickstart-static64.sh)</span></span></code></pre></div><p>这将下载并安装启动和运行 Netdata 所需的一切。</p><p>有些用户可能不想在没有研究的情况下将某些东西直接注入到 Bash。如果你不喜欢此方法，可以按照以下步骤在系统上安装它。</p><h4 id="在-arch-linux-上" tabindex="-1">在 Arch Linux 上 <a class="header-anchor" href="#在-arch-linux-上" aria-label="Permalink to “在 Arch Linux 上”">​</a></h4>',14)),i("p",null,[a[1]||(a[1]=s("Arch Linux 默认仓库中提供了最新版本。所以，我们可以使用以下 ",-1)),e(n,{href:"https://www.ostechnix.com/getting-started-pacman/"},{default:t(()=>[...a[0]||(a[0]=[s("pacman",-1)])]),_:1}),a[2]||(a[2]=s(" 命令安装它：",-1))]),a[24]||(a[24]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S netdata</span></span></code></pre></div><h4 id="在基于-deb-和基于-rpm-的系统上" tabindex="-1">在基于 DEB 和基于 RPM 的系统上 <a class="header-anchor" href="#在基于-deb-和基于-rpm-的系统上" aria-label="Permalink to “在基于 DEB 和基于 RPM 的系统上”">​</a></h4><p>在基于 DEB （Ubuntu / Debian）或基于 RPM（RHEL / CentOS / Fedora） 系统的默认仓库没有 NetData。我们需要从它的 Git 仓库手动安装 NetData。</p><p>首先安装所需的依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Debian / Ubuntu</span></span>
<span class="line"><span>$ sudo apt-get install zlib1g-dev uuid-dev libuv1-dev liblz4-dev libjudy-dev libssl-dev libmnl-dev gcc make git autoconf autoconf-archive autogen automake pkg-config curl</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Fedora</span></span>
<span class="line"><span>$ sudo dnf install zlib-devel libuuid-devel libuv-devel lz4-devel Judy-devel openssl-devel libmnl-devel gcc make git autoconf autoconf-archive autogen automake pkgconfig curl findutils</span></span>
<span class="line"><span></span></span>
<span class="line"><span># CentOS / Red Hat Enterprise Linux</span></span>
<span class="line"><span>$ sudo yum install epel-release</span></span>
<span class="line"><span>$ sudo yum install autoconf automake curl gcc git libmnl-devel libuuid-devel openssl-devel libuv-devel lz4-devel Judy-devel lm_sensors make MySQL-python nc pkgconfig python python-psycopg2 PyYAML zlib-devel</span></span>
<span class="line"><span></span></span>
<span class="line"><span># openSUSE</span></span>
<span class="line"><span>$ sudo zypper install zlib-devel libuuid-devel libuv-devel liblz4-devel judy-devel openssl-devel libmnl-devel gcc make git autoconf autoconf-archive autogen automake pkgconfig curl findutils</span></span></code></pre></div><p>安装依赖项后，在基于 DEB 或基于 RPM 的系统上安装 NetData，如下所示。</p><p>Git 克隆 NetData 仓库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/netdata/netdata.git --depth=100</span></span></code></pre></div><p>上面的命令将在当前工作目录中创建一个名为 <code>netdata</code> 的目录。</p><p>切换到 <code>netdata</code> 目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd netdata/</span></span></code></pre></div><p>最后，使用命令安装并启动 NetData：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./netdata-installer.sh</span></span></code></pre></div><p><strong>示例输出：</strong></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Welcome to netdata!</span></span>
<span class="line"><span>Nice to see you are giving it a try!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>You are about to build and install netdata to your system.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>It will be installed at these locations:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- the daemon at /usr/sbin/netdata</span></span>
<span class="line"><span> - config files at /etc/netdata</span></span>
<span class="line"><span> - web files at /usr/share/netdata</span></span>
<span class="line"><span> - plugins at /usr/libexec/netdata</span></span>
<span class="line"><span> - cache files at /var/cache/netdata</span></span>
<span class="line"><span> - db files at /var/lib/netdata</span></span>
<span class="line"><span> - log files at /var/log/netdata</span></span>
<span class="line"><span> - pid file at /var/run</span></span>
<span class="line"><span></span></span>
<span class="line"><span>This installer allows you to change the installation path.</span></span>
<span class="line"><span>Press Control-C and run the same command with --help for help.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Press ENTER to build and install netdata to your system &gt; ## Press ENTER key</span></span></code></pre></div><p>安装完成后，你将在最后看到以下输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-------------------------------------------------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OK. NetData is installed and it is running (listening to *:19999).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-------------------------------------------------------------------------------</span></span>
<span class="line"><span></span></span>
<span class="line"><span>INFO: Command line options changed. -pidfile, -nd and -ch are deprecated.</span></span>
<span class="line"><span>If you use custom startup scripts, please run netdata -h to see the</span></span>
<span class="line"><span>corresponding options and update your scripts.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Hit http://localhost:19999/ from your browser.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To stop netdata, just kill it, with:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>killall netdata</span></span>
<span class="line"><span></span></span>
<span class="line"><span>To start it, just run it:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/sbin/netdata</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>Enjoy!</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Uninstall script generated: ./netdata-uninstaller.sh</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Deepin-Terminal_002-6.png" alt=""></p><p><em>安装 NetData</em></p><p>NetData 已安装并启动。</p>`,20)),i("p",null,[a[4]||(a[4]=s("要在其他 Linux 发行版上安装 Netdata，请参阅",-1)),e(n,{href:"https://docs.netdata.cloud/packaging/installer/"},{default:t(()=>[...a[3]||(a[3]=[s("官方安装说明页面",-1)])]),_:1}),a[5]||(a[5]=s("。",-1))]),a[25]||(a[25]=l(`<h3 id="在防火墙或者路由器上允许-netdata-的默认端口" tabindex="-1">在防火墙或者路由器上允许 NetData 的默认端口 <a class="header-anchor" href="#在防火墙或者路由器上允许-netdata-的默认端口" aria-label="Permalink to “在防火墙或者路由器上允许 NetData 的默认端口”">​</a></h3><p>如果你的系统在防火墙或者路由器后面，那么必须允许默认端口 <code>19999</code> 以便从任何远程系统访问 NetData 的 web 界面。</p><h4 id="在-ubuntu-debian-中" tabindex="-1">在 Ubuntu/Debian 中 <a class="header-anchor" href="#在-ubuntu-debian-中" aria-label="Permalink to “在 Ubuntu/Debian 中”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw allow 19999</span></span></code></pre></div><h4 id="在-centos-rhel-fedora-中" tabindex="-1">在 CentOS/RHEL/Fedora 中 <a class="header-anchor" href="#在-centos-rhel-fedora-中" aria-label="Permalink to “在 CentOS/RHEL/Fedora 中”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --permanent --add-port=19999/tcp</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><h3 id="启动-停止-netdata" tabindex="-1">启动/停止 NetData <a class="header-anchor" href="#启动-停止-netdata" aria-label="Permalink to “启动/停止 NetData”">​</a></h3><p>要在使用 Systemd 的系统上启用和启动 Netdata 服务，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl enable netdata</span></span>
<span class="line"><span>$ sudo systemctl start netdata</span></span></code></pre></div><p>要停止：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl stop netdata</span></span></code></pre></div><p>要在使用 Init 的系统上启用和启动 Netdata 服务，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo service netdata start</span></span>
<span class="line"><span>$ sudo chkconfig netdata on</span></span></code></pre></div><p>要停止：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo service netdata stop</span></span></code></pre></div><h3 id="通过-web-浏览器访问-netdata" tabindex="-1">通过 Web 浏览器访问 NetData <a class="header-anchor" href="#通过-web-浏览器访问-netdata" aria-label="Permalink to “通过 Web 浏览器访问 NetData”">​</a></h3><p>打开 Web 浏览器，然后打开 <code>http://127.0.0.1:19999</code> 或者 <code>http://localhost:19999/</code> 或者 <code>http://ip-address:19999</code>。你应该看到如下页面。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Netdata-dashboard.png" alt=""></p><p><em>Netdata 仪表板</em></p><p>在仪表板中，你可以找到 Linux 系统的完整统计信息。向下滚动以查看每个部分。</p><p>你可以随时打开 <code>http://localhost:19999/netdata.conf</code> 来下载和/或查看 NetData 默认配置文件。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2016/06/Netdata-config-file.png" alt=""></p><p><em>Netdata 配置文件</em></p><h3 id="更新-netdata" tabindex="-1">更新 NetData <a class="header-anchor" href="#更新-netdata" aria-label="Permalink to “更新 NetData”">​</a></h3><p>在 Arch Linux 中，只需运行以下命令即可更新 NetData。如果仓库中提供了更新版本，那么就会自动安装该版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -Syyu</span></span></code></pre></div><p>在基于 DEB 或 RPM 的系统中，只需进入已克隆它的目录（此例中是 <code>netdata</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd netdata</span></span></code></pre></div><p>拉取最新更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git pull</span></span></code></pre></div><p>然后，使用命令重新构建并更新它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./netdata-installer.sh</span></span></code></pre></div><h3 id="卸载-netdata" tabindex="-1">卸载 NetData <a class="header-anchor" href="#卸载-netdata" aria-label="Permalink to “卸载 NetData”">​</a></h3><p>进入克隆 NetData 的文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd netdata</span></span></code></pre></div><p>然后，使用命令卸载它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ./netdata-uninstaller.sh --force</span></span></code></pre></div><p>在 Arch Linux 中，使用以下命令卸载它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -Rns netdata</span></span></code></pre></div><h3 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to “资源”">​</a></h3>`,40)),i("ul",null,[i("li",null,[e(n,{href:"http://netdata.firehol.org/"},{default:t(()=>[...a[6]||(a[6]=[s("NetData 网站",-1)])]),_:1})]),i("li",null,[e(n,{href:"https://github.com/firehol/netdata"},{default:t(()=>[...a[7]||(a[7]=[s("NetData 的 GitHub 页面",-1)])]),_:1})])]),a[26]||(a[26]=i("hr",null,null,-1)),i("p",null,[a[9]||(a[9]=s("via: ",-1)),e(n,{href:"https://www.ostechnix.com/netdata-real-time-performance-monitoring-tool-linux/"},{default:t(()=>[...a[8]||(a[8]=[s("https://www.ostechnix.com/netdata-real-time-performance-monitoring-tool-linux/",-1)])]),_:1})]),i("p",null,[a[14]||(a[14]=s("作者：",-1)),e(n,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...a[10]||(a[10]=[s("sk",-1)])]),_:1}),a[15]||(a[15]=s(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...a[11]||(a[11]=[s("lujun9972",-1)])]),_:1}),a[16]||(a[16]=s(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...a[12]||(a[12]=[s("geekpi",-1)])]),_:1}),a[17]||(a[17]=s(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...a[13]||(a[13]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[20]||(a[20]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...a[18]||(a[18]=[s("LCTT",-1)])]),_:1}),a[21]||(a[21]=s(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...a[19]||(a[19]=[s("Linux中国",-1)])]),_:1}),a[22]||(a[22]=s(" 荣誉推出",-1))])])}const v=p(h,[["render",c]]);export{x as __pageData,v as default};
